"""SubTaskAuditor — 独立验证器。

参考 LongHorizon 的独立审计设计：
- 在独立上下文中验证 Executor 的输出
- 检查输出是否符合子任务的预期
- 对比执行证据（工具调用结果）
- 生成审计报告（通过/失败/需重试）

三种审计策略：
1. 规则审计：检查输出非空、格式正确等基础规则
2. LLM 审计：让 LLM 评估输出质量（用于关键子任务）
3. 证据审计：检查工具调用是否成功
"""
import json
import logging

logger = logging.getLogger("agent.orchestration.auditor")


# LLM 审计提示词
_AUDITOR_PROMPT = """\
你是独立的质量审计员。请评估以下子任务的执行结果。

子任务描述：{description}
预期输出：{expected_output}

实际执行结果：
{result}

执行证据：
{evidence}

请评估以下维度并回复 JSON：
{{
  "passed": true/false,
  "confidence": 0.0-1.0,
  "issues": ["发现的问题列表"],
  "suggestions": ["改进建议"],
  "should_retry": true/false
}}
"""


class AuditResult:
    """审计结果。"""

    def __init__(self, passed, confidence=1.0, issues=None,
                 suggestions=None, should_retry=False, method='rule'):
        self.passed = passed
        self.confidence = confidence
        self.issues = issues or []
        self.suggestions = suggestions or []
        self.should_retry = should_retry
        self.method = method

    def to_dict(self):
        return {
            'passed': self.passed,
            'confidence': self.confidence,
            'issues': self.issues,
            'suggestions': self.suggestions,
            'should_retry': self.should_retry,
            'method': self.method,
        }


class SubTaskAuditor:
    """子任务独立验证器。"""

    def __init__(self, llm_client=None):
        self.llm = llm_client

    def audit(self, subtask):
        """审计子任务的执行结果。

        参数:
            subtask: SubTask 实例（已完成执行）

        返回:
            AuditResult 实例
        """
        # 1. 规则审计（始终执行）
        rule_result = self._audit_rules(subtask)
        if not rule_result.passed:
            logger.info('子任务 %s 规则审计未通过: %s',
                        subtask.id, rule_result.issues)
            return rule_result

        # 2. 证据审计（检查工具调用）
        evidence_result = self._audit_evidence(subtask)
        if not evidence_result.passed:
            logger.info('子任务 %s 证据审计未通过: %s',
                        subtask.id, evidence_result.issues)
            return evidence_result

        # 3. LLM 审计（可选，用于关键子任务）
        if self.llm and self._needs_llm_audit(subtask):
            try:
                llm_result = self._audit_with_llm(subtask)
                logger.info('子任务 %s LLM 审计: passed=%s conf=%.2f',
                            subtask.id, llm_result.passed,
                            llm_result.confidence)
                return llm_result
            except Exception:
                logger.debug('LLM 审计失败，使用规则审计结果',
                             exc_info=True)

        return rule_result

    def _audit_rules(self, subtask):
        """规则审计：基础检查。"""
        issues = []

        # 检查输出非空
        if not subtask.result:
            issues.append('输出为空')

        # 检查输出长度合理
        result_str = str(subtask.result) if subtask.result else ''
        if len(result_str) > 50000:
            issues.append('输出过长（%d 字符）' % len(result_str))

        # 检查是否有错误标记
        if subtask.evidence and isinstance(subtask.evidence, dict):
            if subtask.evidence.get('error'):
                issues.append('执行证据包含错误: %s' %
                              subtask.evidence['error'])

        passed = len(issues) == 0
        return AuditResult(
            passed=passed,
            confidence=0.9 if passed else 0.3,
            issues=issues,
            should_retry=not passed,
            method='rule')

    def _audit_evidence(self, subtask):
        """证据审计：检查工具调用是否成功。"""
        if not subtask.evidence or not isinstance(subtask.evidence, dict):
            return AuditResult(passed=True, confidence=0.8,
                               method='evidence')

        issues = []
        tool_calls = subtask.evidence.get('tool_calls', [])
        for tc in tool_calls:
            result_str = str(tc.get('result_summary', ''))
            if 'error' in result_str.lower() or '失败' in result_str:
                issues.append('工具 %s 可能失败: %s' % (
                    tc.get('tool', '?'), result_str[:100]))

        passed = len(issues) == 0
        return AuditResult(
            passed=passed,
            confidence=0.85 if passed else 0.4,
            issues=issues,
            should_retry=not passed and len(tool_calls) > 0,
            method='evidence')

    def _needs_llm_audit(self, subtask):
        """判断是否需要 LLM 审计。"""
        # 当规则审计和证据审计都通过但子任务较复杂时，使用 LLM 审计
        return (subtask.evidence
                and isinstance(subtask.evidence, dict)
                and len(subtask.evidence.get('tool_calls', [])) >= 2)

    def _audit_with_llm(self, subtask):
        """LLM 审计：让 LLM 评估输出质量。"""
        evidence_str = json.dumps(
            subtask.evidence, ensure_ascii=False, indent=2)[:1000]

        response = self.llm.quick_prompt(
            system='你是独立的质量审计员。只回复 JSON。',
            user=_AUDITOR_PROMPT.format(
                description=subtask.description,
                expected_output=subtask.expected_output or '（未指定）',
                result=str(subtask.result)[:2000],
                evidence=evidence_str),
            skill='orchestration', category='audit',
            json_mode=True)

        data = json.loads(response)
        return AuditResult(
            passed=data.get('passed', True),
            confidence=data.get('confidence', 0.5),
            issues=data.get('issues', []),
            suggestions=data.get('suggestions', []),
            should_retry=data.get('should_retry', False),
            method='llm')
